import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateProductVariantsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateProductVariantsWorkflow(req.scope)
    .run({
      input: {
        product_variants: [{
            id: "variant_123",
            prices: [{
              amount: 10,
              currency_code: "usd",
            }]
          },
          {
            id: "variant_321",
            title: "Small Shirt",
          },
        ],
        additional_data: {
          erp_id: "123"
        }
      }
    })

  res.send(result)
}

