import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateProductVariantsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateProductVariantsWorkflow(req.scope)
    .run({
      input: {
        selector: {
          product_id: "prod_123"
        },
        update: {
          prices: [{
            amount: 10,
            currency_code: "usd"
          }]
        },
        additional_data: {
          erp_id: "123"
        }
      }
    })

  res.send(result)
}

